#!/usr/bin/env python3
"""One-off corrections to taxi/airtaxi.template.html from the 28 Oct 2026 review (air-taxi claims audit, coverage and audience reviews),
matched to the engine-v5 display export (taxi/export_airtaxi.js). Each edit asserts it matches exactly once. Run once from the repo root."""
import sys
P = 'taxi/airtaxi.template.html'; s = open(P, encoding='utf8').read(); n = 0
def rep(old, new):
    global s, n
    c = s.count(old)
    if c != 1: sys.exit(f'count {c}: {old[:100]!r}')
    s = s.replace(old, new); n += 1

SITES_DESC = 'between airports and sites Joby has flown to in North Texas, Houston airports in Wisk’s plans, and the downtown Dallas vertiport (closed for rebuilding)'
rep('air-taxi networks for Dallas–Fort Worth and Houston on the routes Joby, Archer and Wisk have flown or named, with aircraft flying, holding and parking in 3D.',
    'air-taxi networks for Dallas–Fort Worth and Houston ' + SITES_DESC + ', with aircraft flying, landing and parking in 3D.')
rep('<p>The sites Joby, Archer and Wisk have flown to or named, linked into one small network per metro. Every aircraft here is a simulation: demand, fleet and pads are assumptions, not a real schedule.</p>',
    '<p>One small network per metro, ' + SITES_DESC + '. Every aircraft here is a simulation: demand, fleet, pads and parking are assumptions, not a real schedule.</p>')
rep('<span class="nl">Flights a day heard at 55 dBA or more (a busy street)</span>'.replace('span', 'div') if False else '<div class="nl">Flights a day heard at 55 dBA or more (a busy street)</div>',
    '<div class="nl">Flights in 12 daytime hours heard at 55 dBA or more (a busy street), this run</div>')
rep('<div class="row"><span><i class="dot" style="background:var(--hold)"></i>Holding for a pad</span>',
    '<div class="row"><span><i class="dot" style="background:var(--hold)"></i>Holding for a pad or stand</span>')
rep('<div class="row legend opt"><span style="font-size:11px;color:var(--ink3)">Heights drawn 6× taller than real so the climb shows.</span></div>',
    '<div class="row legend"><span style="font-size:11px;color:var(--ink3)">Not to scale: aircraft drawn about 150× life size, pads and holding circles enlarged, heights 6×.</span></div>')

# ---- drawer ----
rep('<p>Car times are Google Maps “typically” ranges for a Wednesday (read once, 26 Oct 2026). Car ranges are for the first-named direction. Air time is request to landing in a well-supplied network. <b>Break-even</b> is how many minutes of getting to and from the pads, in total, before flying stops beating the peak-hour car.</p>',
    '<p>Car times are Google Maps “typically” ranges for a Wednesday (read once, 26 Oct 2026), shown for the first-named direction. Air time is request to landing in a well-supplied network (no queueing). <b>Break-even</b> is how many minutes of getting to and from the pads, in total (including check-in and boarding), before flying stops beating the peak-hour car. It is averaged over both directions and the 08:00 and 17:30 peaks, so it cannot be worked out from the columns shown (AIRTAXI_NET1, engine v2; not rerun on later engines, which change queueing, not flight times).</p>')
rep('<h3>Assumptions (none of these are public)</h3>',
    '<h3>Assumptions</h3><p style="margin:0 0 4px">From public sources: four seats and a 2,000 ft cruise (Archer’s design figures), the FAA’s 8:1 vertiport obstacle surface, the charging rate (Archer marketing). Not public, so assumed here: pad count and pad time, parking stands, demand, aircraft range and how the network is run.</p>')
rep('<li>Four-seat aircraft, one party per flight, 150 mph cruise at 2,000 ft, climbing along the FAA’s 8:1 vertiport path; 100 km of usable range, charging about 10 minutes per 20 miles flown.</li>',
    '<li>Four-seat aircraft, one party per flight, 150 mph cruise at 2,000 ft (the cruise speed is not verified for any operator), climbing at 8:1, the shallowest slope the FAA’s vertiport obstacle surface allows (the surface is defined for clearance, not as a flight path); 100 km usable plus the FAA’s 20-minute reserve; charging about 10 minutes per 20 miles flown. Holding uses battery.</li>')
rep('<li>Every site has 2 landing pads; each take-off or landing holds a pad for 90 s; 5 minutes to unload and board. Demand is spread evenly over the day.</li>',
    '<li>Pads and parking stands per site change with demand, as the studies found workable: 2 pads and 6 to 8 stands at the two lower levels, 4 pads and 10 to 12 stands at the highest. Each take-off or landing holds a pad for 90 s; 5 minutes to unload and board. The landing slot is booked at take-off, and an aircraft with no free stand at its destination holds until one frees. Demand is spread evenly over 12 daytime hours (06:00–18:00).</li>')
rep('<li>Downtown Dallas (49T) is closed for rebuilding, with reopening reported for about 2029. It is shown as a future site.</li>',
    '<li>Downtown Dallas (49T) is closed for rebuilding; reopening is reported for about 2029 (Wikipedia, not confirmed). <b>The model flies it as if it were open</b>; it is drawn dimmer and its route is marked. None of the company announcements used here names it.</li>\n    <li>Engine v5 (27 Oct 2026). One random day per setting; this run uses the fleet the studies found for that day, which can be one or two aircraft above the study’s central figure.</li>')
rep('<p>The noise layer counts, for each 200 m square, how many of this run’s flights reach 55 dBA or more there over the 12 hours. It uses Joby’s reported levels (about 45 dBA at 500 m in cruise, under 65 dBA at 100 m on take-off and landing), simple spreading on flat ground, and departure paths pointed at the next site because real ones are not public. Loud noise stays within about 2.4 km of a site; nowhere more than 300 m from a site comes near the FAA’s 65 dB day–night threshold (highest 54 dB in the study). What adds up is how often: about 15 loud flights an hour 1 km out from DFW Airport at 48 trips an hour.</p>',
    '<p>The noise layer counts, for each 200 m square, how many of this run’s flights reach 55 dBA or more there over the 12 hours. It uses Joby’s reported levels (about 45 dBA from a 500 m flyover at 100 knots in a NASA test, applied here at cruise; under 65 dBA at 100 m on take-off and landing), simple spreading on flat ground, holding as a hover 150 m over the site, and departure paths pointed at the next site because real ones are not public. Loud noise stays within about 2.4 km of a site; nowhere more than 300 m from a site comes near the FAA’s 65 dB day–night threshold (highest 54 dB in the study). The day–night level here counts 12 daytime hours only, with no evening or night flights; if the aircraft were 5 dB louder, loud noise would reach about 4.4 km. What adds up is how often: about 15 loud flights an hour 1 km out from DFW Airport at 48 trips an hour, along the assumed straight departure line (AIRTAXI_NOISE1; one of its six predictions, about these counts, failed). The city blocks are left out near sites so the pads stay visible: people do live there.</p>')
rep('''  <h3>Main study results</h3>
  <ul>
    <li><b>Break-even access time</b> at peak: 20 minutes (DFW Airport–Toyota) to 44 minutes (Alliance–Toyota). At 20 minutes of getting to and from pads, the air taxi beats the peak car on all six routes; at 40, only on Alliance–Toyota.</li>
    <li><b>Aircraft needed</b> (95 % served, median wait under 10 min): about 8 for 12 trips an hour in DFW, 5 for 6 trips an hour in Houston; about 1.6–1.75 times as many when demand doubles.</li>
    <li><b>Pads:</b> 2 pads cope up to about 30 take-offs and landings an hour at a site; DFW Airport needs 4 at 48 trips an hour on the network. If a take-off or landing holds a pad 3 minutes instead of 90 s, the pads needed roughly double.</li>
  </ul>
  <p>Each study was written down and fingerprinted before it ran, and failed predictions stay in the record: <a href="https://github.com/forgottenl5/sky-grid/tree/main/planned">study files</a>. Not affiliated with Joby, Archer, Wisk, Toyota, any airport or the FAA; not flight data, a forecast or safety advice.</p>''',
'''  <h3>Main study results</h3>
  <ul>
    <li><b>Break-even access time</b> at peak: 20 minutes (DFW Airport–Toyota) to about 45 minutes (Alliance–Toyota). At 20 minutes of getting to and from pads, the air taxi ties the car on DFW Airport–Toyota and loses in the morning toward Toyota; at 40, it wins only on Alliance–Toyota (NET1).</li>
    <li><b>Who would save time:</b> on Archer’s announced network of twelve Texas sites (a larger set than this page’s), only about 1.2 % of DFW jobs and 0.5 % of Houston jobs have a commute that flying would shorten by 10 minutes or more at peak, and the range is wide (DFW 0.02–4.9 %, Houston 0.2–2.4 %). Those who would gain mostly commute long distances across the metro (ACCESS1, UNCERT1).</li>
    <li><b>Aircraft needed</b> (95 % served, median wait under 10 min): about 8 for 12 trips an hour in DFW and 5 for 6 trips an hour in Houston; about 1.6–2 times as many each time demand doubles. When the uncertain inputs vary, DFW at 24 trips an hour needs 12–16 and Houston at 12 trips an hour 8–12; the charging rate moves it most (NET2, NET3, UNCERT1).</li>
    <li><b>Pads:</b> with unlimited parking, 2 pads cope at the lowest demand; at 48 trips an hour DFW needs 4, and Houston needs 3 at 24 (NET2). If a take-off or landing holds a pad 3 minutes instead of 90 s, the pads needed roughly double.</li>
    <li><b>Parking and the landing rule:</b> with limited stands, how landings are granted matters more than the stand count. With 2 pads, first come, first served at arrival never met the service and battery-reserve test at 24 trips an hour (DFW); booking the landing slot at take-off needed 8 stands per site, and holding aircraft on the ground until a stand is reserved needed 5 but made passengers wait longer (STANDS1, PADRULE1). This page uses the slot rule, which is why holding is rare here.</li>
    <li><b>Battery reserve:</b> with a 130 km battery and the FAA’s 20-minute reserve, three of the six routes could not be flown at all; the fleets above assume 100 km usable after the reserve (NET3).</li>
    <li><b>Drones near the sites:</b> at full delivery-drone build-out about 1 in 3 take-offs and landings at Toyota’s Plano HQ would have a drone inside the “well clear” volume on planned paths; drones yielding to booked air-taxi movements removes all of them (AIRTAXI1, VTXPAD).</li>
    <li><b>Outside check:</b> the engine reproduces a published MIT vertiport-capacity study (Vascik &amp; Hansman, 2019) in 5 of 5 predictions; that check covers one vertiport, not the network, energy or demand (VERTIPORT1).</li>
  </ul>
  <p>Since 22 Oct 2026 each study was written down and fingerprinted before it ran, and failed predictions stay in the record: 18 of the 70 predictions in the nine air-taxi studies failed. The full record is private for now and available on request; the main results are on the <a href="findings.html">findings page</a>, and the delivery-drone studies in the <a href="lab.html">Lab</a>. Map data: city blocks from US Census 2020 and LODES 2022 jobs (schematic, heights from job counts); downtown buildings © OpenStreetMap contributors (ODbL). Not affiliated with Joby, Archer, Wisk, Toyota, any airport or the FAA; not flight data, a forecast or safety advice.</p>''')

# ---- run text, level buttons ----
rep("b.title = `${l.fleet} aircraft`;", "b.title = `${l.fleet} aircraft, ${l.pads} pads and ${l.stands} stands per site`;")
rep("$('runsub').textContent = `${L.tripsPerHour} trips an hour · ${L.fleet} aircraft · one run`;",
    "$('runsub').textContent = `${L.tripsPerHour} trips an hour · ${L.fleet} aircraft · ${L.pads} pads, ${L.stands} stands per site`;")
rep("$('runtxt').textContent = `${metro === 'DFW' ? 'Dallas–Fort Worth' : 'Houston'}, ${L.tripsPerHour} trip requests an hour spread over the day, ${L.fleet} aircraft. Over the 12 hours ${s.served} of ${s.requests} requests were flown (${Math.round(100 * s.served / s.requests)} %), median wait ${s.medianWaitMin} min; ${Math.round(100 * s.deadheadShare)} % of flights were empty repositioning flights. One run of one random day; the studies average ten.`;",
    "$('runtxt').textContent = `${metro === 'DFW' ? 'Dallas–Fort Worth' : 'Houston'}, ${L.tripsPerHour} trip requests an hour spread over 12 daytime hours, ${L.fleet} aircraft, ${L.pads} pads and ${L.stands} parking stands per site. Over the 12 hours ${s.served} of ${s.requests} requests were flown (${(100 * s.served / s.requests).toFixed(1)} %), median wait ${s.medianWaitMin} min; ${Math.round(100 * s.deadheadShare)} % of flights were empty repositioning flights; at most ${Math.max(...Object.values(s.maxParked))} aircraft were parked at one site. This setup meets the studies’ service and battery-reserve test on this random day. The studies’ central fleet for this demand is ${L.studyFleet}${L.studyRange ? ` (${L.studyRange[0]}–${L.studyRange[1]} when the uncertain inputs vary)` : ''}; this day needs ${L.fleet}. One run of one day; the studies use ten.`;")
rep("$('rtab').innerHTML = M.routes.map(r => `<tr><td>${sites[r.a].name.split(' (')[0]} ↔ ${sites[r.b].name.split(' (')[0]}<br>",
    "$('rtab').innerHTML = M.routes.map(r => `<tr><td>${sites[r.a].name.split(' (')[0]} ↔ ${sites[r.b].name.split(' (')[0]}${sites[r.a].closed || sites[r.b].closed ? ' <span style=\"color:var(--hold);font-size:11px\">(site closed until about 2029)</span>' : ''}<br>")

# ---- drawing: pads per level, closed site dimmer ----
rep("// two landing pads per site: each aircraft uses one side, blended in over the last 1.6 km so arrivals do not merge\nfunction laneOf(i) { return (i % 2 ? 1 : -1) * 0.8; }",
    "// landing pads per site (2 or 4 by demand level): each aircraft uses one lane, blended in over the last 1.6 km so arrivals do not merge (drawn enlarged)\nfunction padXs() { return L && L.pads === 4 ? [-1.05, -0.35, 0.35, 1.05] : [-0.8, 0.8]; }\nfunction laneOf(i) { const xs = padXs(); return xs[i % xs.length]; }")
rep("  // sites: two pads, a ring and a soft beam\n  for (const s of M.sites) { const g = new THREE.Group(); g.position.copy(V({ x: s.x * KM, y: s.y * KM, z: 0 }));\n    const ring = new THREE.Mesh(new THREE.RingGeometry(1.75, 1.9, 64), new THREE.MeshBasicMaterial({ color: C.site, transparent: true, opacity: 0.7, side: THREE.DoubleSide })); ring.rotation.x = -Math.PI / 2; g.add(ring);\n    for (const o of [-0.8, 0.8]) { const pad = new THREE.Mesh(new THREE.CircleGeometry(0.55, 32), new THREE.MeshBasicMaterial({ color: C.site, transparent: true, opacity: 0.35 })); pad.rotation.x = -Math.PI / 2; pad.position.set(o, 0.01, 0); g.add(pad); }\n    const beam = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.3, 6, 12, 1, true), new THREE.MeshBasicMaterial({ color: C.site, transparent: true, opacity: 0.08, side: THREE.DoubleSide })); beam.position.y = 3; g.add(beam);",
    "  // sites: one disc per pad (2 or 4 by level), a ring and a soft beam; a closed site (49T) is drawn dimmer\n  for (const s of M.sites) { const g = new THREE.Group(); g.position.copy(V({ x: s.x * KM, y: s.y * KM, z: 0 })); const dim = s.closed ? 0.45 : 1, pr = L.pads === 4 ? 0.32 : 0.55;\n    const ring = new THREE.Mesh(new THREE.RingGeometry(1.75, 1.9, 64), new THREE.MeshBasicMaterial({ color: C.site, transparent: true, opacity: 0.7 * dim, side: THREE.DoubleSide })); ring.rotation.x = -Math.PI / 2; g.add(ring);\n    for (const o of padXs()) { const pad = new THREE.Mesh(new THREE.CircleGeometry(pr, 32), new THREE.MeshBasicMaterial({ color: C.site, transparent: true, opacity: 0.35 * dim })); pad.rotation.x = -Math.PI / 2; pad.position.set(o, 0.01, 0); g.add(pad); }\n    const beam = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.3, 6, 12, 1, true), new THREE.MeshBasicMaterial({ color: C.site, transparent: true, opacity: 0.08 * dim, side: THREE.DoubleSide })); beam.position.y = 3; g.add(beam);")
rep("el.innerHTML = `<b>${s.name}</b><span></span>`;", "el.innerHTML = `<b>${s.name}</b><span></span>`; if (s.closed) el.style.opacity = '0.75';")
rep("if (tt < f[5]) { const w = (tt - f[4]) / 60, r = 2600; /* drawn wider than the modelled 900 m hold so it reads beside the pad ring */ return { x: (b.x + Math.cos(w) * r) * KM, y: (b.y + Math.sin(w) * r) * KM, z: 150 * KM * VX, hold: true }; }   // hold: orbit 900 m out at 150 m",
    "if (tt < f[5]) { const w = (tt - f[4]) / 60, r = 2600; /* the engine only counts holding time; it is drawn as a 2.6 km circle at 150 m so it reads outside the site ring */ return { x: (b.x + Math.cos(w) * r) * KM, y: (b.y + Math.sin(w) * r) * KM, z: 150 * KM * VX, hold: true }; }")
rep("// ---- aircraft: a small tilt-rotor eVTOL drawn far larger than life (about 700 m wingspan) so it reads at metro scale",
    "// ---- aircraft: a small tilt-rotor eVTOL drawn far larger than life (about 1.8 km wingspan, about 150× life size) so it reads at metro scale")

# ---- captions ----
rep("capSet('', 'One aircraft.', 'Four seats. Up steeply, cruise, then down onto a pad, all flown by a model.', false, true);",
    "capSet('', 'One aircraft.', 'Four seats. A short vertical lift, a long shallow climb (heights drawn 6× taller), cruise, then down onto a pad. All simulated.', false, true);")
rep("capSet('', 'Sometimes it waits.', 'Holding in the air for a free landing pad. Pads and their time are assumptions.', true, true);",
    "capSet('', 'Sometimes it waits.', 'Holding for a free pad or parking stand. Rare here, because the landing slot is booked at take-off.', true, true);")
rep("capSet('', 'One simulated weekday.', '', false, false);", "capSet('', 'Twelve simulated daytime hours.', '', false, false);")
rep("capSet('Holding for a free pad', '', '', true);", "capSet('Holding for a free pad or stand', '', '', true);")
rep('<div id="capF">A simulation, not a real schedule: assumed demand, fleet and pads.</div>',
    '<div id="capF">A simulation, not a real schedule: assumed demand, fleet, pads and parking. Not to scale.</div>')
open(P, 'w', encoding='utf8').write(s); print(n, 'edits')
